const tabId = 1675924566;

// Let's search USC Bookstore for specific terms: "diploma frame", "alumni", "dad", "mom", "hydro flask" or "tumbler"
const queries = ["diploma frame", "alumni", "mom", "dad", "backpack"];

for (const q of queries) {
  await tool.navigate({ tabId, url: `https://www.uscbookstore.com/search?keywords=${encodeURIComponent(q)}` });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

  const results = await browserjs(tabId, () => {
    // Close modal if present
    const closeBtn = document.querySelector('[data-action-close], .x-btn, .email-lead-modal-popup button');
    if (closeBtn) closeBtn.click();
    const overlay = document.querySelector('.email-lead-modal-popup');
    if (overlay) overlay.style.display = 'none';

    const cards = Array.from(document.querySelectorAll('[data-view="Facets.ItemCell"], .facets-item-cell-grid'));
    return cards.slice(0, 5).map(c => {
      const title = c.querySelector('a.facets-item-cell-grid-title, [itemprop="name"]')?.textContent?.trim();
      const price = c.querySelector('.product-views-price-lead')?.textContent?.trim();
      const oldPrice = c.querySelector('.product-views-price-old')?.textContent?.trim();
      const link = c.querySelector('a')?.href;
      return { title, price, oldPrice, link };
    }).filter(x => x.title);
  });

  console.log(`Query "${q}" results (${results.length}):`);
  console.log(JSON.stringify(results, null, 2));
}

