  { id: 1675924569, role: "Alum: $25-$60 (USC Bookstore Alumni Frame)" },
  { id: 1675924570, role: "Parent: $25-$60 (USC Bookstore Mom Sweatshirt)" },
  { id: 1675924571, role: "Parent: >$60 (USC Bookstore Sherpa Throw)" },
  { id: 1675924572, role: "General Fan: $25-$60 (Fanatics Autographed Helmet)" },
  { id: 1675924573, role: "General Fan: >$60 (Fanatics Nike Jersey)" },
