  { id: 1675924568, role: "Policy: USC Bookstore Return Policy" }
];

const results = [];
for (const item of tabList) {
  await tool.wait_for({ tabId: item.id, condition: "dom_settled", timeout_ms: 4000 });
  const data = await browserjs(item.id, () => {
    // dismiss USC bookstore modal if present
