  1675924573  // Fanatics Nike Jersey
];

const detailedData = {};

for (const tid of tabsToInspect) {
  detailedData[tid] = await browserjs(tid, () => {
    const title = document.querySelector('h1')?.textContent?.trim();
    const price = document.querySelector('.product-views-price-lead, .price-card, .product-price, .regular-price')?.textContent?.trim();
